import type { Experimental_EvaluationModel as EvaluationModel } from 'ai';
import { interruptible, RunInterruptedError, throwIfInterrupted, type ExecutionOptions } from '../cancellation.js';
import { resolveEvaluationConfiguration, validateCloudflareAccountId, validateEvaluationModel, type EvaluationConfiguration } from '../config.js';
import { redactSensitiveText, withRedactionSecrets } from '../logging/trace.js';
import type { AgentState, EvaluationResult } from '../types.js';
import { boundAgentStateForEvaluation } from './contract.js';
import {
  evaluationRetryDelay, isTransientEvaluationError, EVALUATION_MAX_RETRIES,
  EVALUATION_TIMEOUT_MS, normalizeEvaluationError,
} from './errors.js';
import { evaluateNative } from './native.js';
import { evaluateVercel } from './vercel.js';
import { evaluateCloudflare } from './cloudflare.js';

export { boundAgentStateForEvaluation } from './contract.js';
export { EvaluationError, EVALUATION_MAX_RETRIES, EVALUATION_TIMEOUT_MS, normalizeEvaluationError } from './errors.js';
export type { EvaluationErrorCode } from './errors.js';
export { JevEvaluationError, JEV_EVALUATION_MAX_RETRIES, JEV_EVALUATION_TIMEOUT_MS, normalizeJevEvaluationError } from './errors.js';
export type { JevEvaluationErrorCode } from './errors.js';

/** Loop-owned routing context; never restored from task text or an approved candidate. */
export type EvaluationOptions = ExecutionOptions & { iterationLimit?: number };

export type Evaluator = (state: AgentState, options?: EvaluationOptions) => Promise<EvaluationResult>;

/** Bind transport credentials and model once, outside serializable run state. */
export function createEvaluator(
  configuration: EvaluationConfiguration = resolveEvaluationConfiguration(),
  modelOverride?: EvaluationModel,
): Evaluator {
  const selected = Object.freeze({ ...configuration, model: typeof modelOverride === 'string' ? modelOverride : configuration.model });
  validateEvaluationModel(selected.provider, selected.model);
  if (selected.provider === 'cloudflare') validateCloudflareAccountId(selected.accountId);
  if (modelOverride !== undefined && typeof modelOverride !== 'string' && selected.provider !== 'vercel') {
    throw new Error('An SDK evaluation model override requires ROUTER_PROVIDER=vercel.');
  }
  return (state, options = {}) => withRedactionSecrets([selected.apiKey], () =>
    evaluateConfiguredState(state, selected, options, typeof modelOverride === 'string' ? undefined : modelOverride));
}

function waitForRetry(milliseconds: number, signal: AbortSignal): Promise<void> {
  throwIfInterrupted(signal);
  return new Promise((resolve, reject) => {
    const finish = (): void => {
      signal.removeEventListener('abort', abort);
      resolve();
    };
    const timer = setTimeout(finish, milliseconds);
    const abort = (): void => {
      clearTimeout(timer);
      signal.removeEventListener('abort', abort);
      reject(new RunInterruptedError());
    };
    signal.addEventListener('abort', abort, { once: true });
  });
}

export async function evaluateAgentState(
  state: AgentState,
  model?: EvaluationModel,
  options: EvaluationOptions = {},
): Promise<EvaluationResult> {
  throwIfInterrupted(options.signal);
  return createEvaluator(resolveEvaluationConfiguration(), model)(state, options);
}

async function evaluateConfiguredState(
  state: AgentState,
  configuration: EvaluationConfiguration,
  options: EvaluationOptions,
  modelOverride?: EvaluationModel,
): Promise<EvaluationResult> {
  throwIfInterrupted(options.signal);
  const startedAt = performance.now();
  const snapshot = boundAgentStateForEvaluation(state, options.iterationLimit);
  const deadline = new AbortController();
  const timeout = setTimeout(() => deadline.abort(), EVALUATION_TIMEOUT_MS);
  const signal = options.signal ? AbortSignal.any([options.signal, deadline.signal]) : deadline.signal;
  try {
    for (let attempt = 0; ; attempt += 1) {
      try {
        const result = await interruptible(() => {
          if (configuration.provider === 'cloudflare') return evaluateCloudflare(snapshot, configuration, signal);
          return configuration.provider === 'vercel'
            ? evaluateVercel(snapshot, configuration, signal, modelOverride)
            : evaluateNative(snapshot, { ...configuration, provider: configuration.provider }, signal);
        }, signal);
        throwIfInterrupted(signal);
        return {
          ...result,
          provider: configuration.provider,
          model: redactSensitiveText(configuration.model),
          requestedModel: redactSensitiveText(configuration.model),
          latencyMs: Math.round(performance.now() - startedAt),
        };
      } catch (error) {
        throwIfInterrupted(signal);
        if (attempt >= EVALUATION_MAX_RETRIES || !isTransientEvaluationError(error)) throw error;
        await waitForRetry(evaluationRetryDelay(error), signal);
      }
    }
  } catch (error) {
    throwIfInterrupted(options.signal);
    throw normalizeEvaluationError(deadline.signal.aborted ? new DOMException('', 'TimeoutError') : error, configuration.provider);
  } finally {
    clearTimeout(timeout);
  }
}
import { throwIfInterrupted } from '../cancellation.js';
import { cloudflareModelPath, validateCloudflareAccountId, type CloudflareConfiguration } from '../config.js';
import { redactSensitiveText, sanitizeTraceValue } from '../logging/trace.js';
import type { AgentState } from '../types.js';
import { isRecord, NATIVE_EVALUATION_QUESTIONS, normalizeAssessment, servedModel, type ProviderEvaluation } from './contract.js';
import { EvaluationError, EvaluationHttpError, retryAfterMs } from './errors.js';
import { boundedResponse, parseEvaluationJson } from './transport.js';

function invalidResponse(stage: 'json' | 'answers' = 'answers'): never {
  throw new EvaluationError('invalid_response', 'Cloudflare returned invalid evaluation data.', { stage, category: 'shape' });
}

/** Cloudflare internal codes are not HTTP status codes. Never classify text. */
function cloudflareErrorStatus(body: unknown): number | undefined {
  if (!isRecord(body) || !Array.isArray(body.errors) || !isRecord(body.errors[0])) return undefined;
  switch (body.errors[0].code) {
    case 5007: case 3042: return 404;
    case 5018: case 5016: case 3023: case 3041: case 5035: return 403;
    case 3007: case 3008: return 408;
    case 3036: case 3040: return 429;
    default: return undefined;
  }
}

export async function evaluateCloudflare(
  state: AgentState,
  configuration: CloudflareConfiguration,
  signal: AbortSignal,
): Promise<ProviderEvaluation> {
  throwIfInterrupted(signal);
  validateCloudflareAccountId(configuration.accountId);
  const modelPath = cloudflareModelPath(configuration.model);
  const response = await boundedResponse(await fetch(
    `https://api.cloudflare.com/client/v4/accounts/${configuration.accountId}/ai/run/${modelPath}`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${configuration.apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: configuration.model, state, questions: NATIVE_EVALUATION_QUESTIONS }),
      signal,
      redirect: 'error',
    },
  ), signal);
  let body: unknown;
  try { body = parseEvaluationJson(await response.text()); } catch (error) {
    if (!response.ok) throw new EvaluationHttpError(response.status, retryAfterMs(response.headers.get('retry-after')));
    throw error;
  }
  if (!response.ok) {
    // Workers AI documents "no such model" as HTTP 400 with code 5007.
    const status = response.status === 400 && cloudflareErrorStatus(body) === 404 ? 404 : response.status;
    throw new EvaluationHttpError(status, retryAfterMs(response.headers.get('retry-after')));
  }
  if (isRecord(body) && body.success === false) {
    throw new EvaluationHttpError(cloudflareErrorStatus(body) ?? 400, retryAfterMs(response.headers.get('retry-after')));
  }
  if (!isRecord(body) || body.success !== true || !Array.isArray(body.errors) || body.errors.length !== 0 ||
    !isRecord(body.result) || !isRecord(body.result.answers) ||
    body.result.error !== undefined || body.result.refusal !== undefined) invalidResponse();
  const answers = body.result.answers;
  const names = Object.keys(NATIVE_EVALUATION_QUESTIONS);
  if (Object.keys(answers).length !== names.length || names.some((name) => !Object.hasOwn(answers, name))) invalidResponse();
  const nextAction = answers.nextAction;
  return {
    assessment: normalizeAssessment(answers, isRecord(nextAction) ? nextAction.confidence : undefined, true),
    rawAnswers: sanitizeTraceValue(answers),
    servedModel: redactSensitiveText(servedModel(body.result.model)),
  };
}

import { EvaluationError } from './errors.js';
import { throwIfInterrupted } from '../cancellation.js';

export const MAX_EVALUATION_RESPONSE_BYTES = 64 * 1024;
export const MAX_JEV_RESPONSE_BYTES = MAX_EVALUATION_RESPONSE_BYTES;

/** Reject duplicate object keys before they can hide answers or probabilities. */
export function parseEvaluationJson(text: string): unknown {
  function invalid(): never {
    throw new EvaluationError('invalid_response', 'Decision provider returned invalid JSON evaluation data.', { stage: 'json', category: 'shape' });
  }
  let parsed: unknown;
  try { parsed = JSON.parse(text); } catch { invalid(); }
  const objects: Array<Set<string> | null> = [];
  // Consume whole strings so brackets and escaped quotes in values are inert.
  for (const match of text.matchAll(/"(?:[^"\\]|\\.)*"|[{}[\]]/g)) {
    const token = match[0];
    if (token === '{') objects.push(new Set());
    else if (token === '[') objects.push(null);
    else if (token === '}' || token === ']') objects.pop();
    else {
      let next = match.index + token.length;
      while (/\s/.test(text[next] ?? '')) next += 1;
      if (text[next] !== ':') continue;
      const keys = objects.at(-1);
      const key: string = JSON.parse(token);
      if (!keys || keys.has(key)) invalid();
      keys.add(key);
    }
  }
  return parsed;
}

/** Enforce a byte cap while reading, including chunked and error responses. */
export async function boundedResponse(response: Response, signal: AbortSignal): Promise<Response> {
  if (signal.aborted) {
    void response.body?.cancel().catch(() => undefined);
    throwIfInterrupted(signal);
  }
  if (!response.body) return response;
  const reader = response.body.getReader();
  const abort = (): void => { void reader.cancel().catch(() => undefined); };
  signal.addEventListener('abort', abort, { once: true });
  const chunks: Uint8Array[] = [];
  let size = 0;
  try {
    while (true) {
      const { value, done } = await reader.read();
      throwIfInterrupted(signal);
      if (done) break;
      size += value.byteLength;
      if (size > MAX_EVALUATION_RESPONSE_BYTES) {
        void reader.cancel().catch(() => undefined);
        throw new EvaluationError('invalid_response', 'Decision response exceeded the bounded output limit.', { stage: 'transport', category: 'size' });
      }
      chunks.push(value);
    }
  } finally {
    signal.removeEventListener('abort', abort);
    reader.releaseLock();
  }
  return new Response(Buffer.concat(chunks), {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  });
}
import { createGateway, experimental_evaluate as evaluate, type Experimental_EvaluationModel as EvaluationModel } from 'ai';
import type { AgentState } from '../types.js';
import type { EvaluationConfiguration } from '../config.js';
import { sanitizeTraceValue } from '../logging/trace.js';
import { EVALUATION_QUESTIONS, normalizeAssessment, nextActionConfidence, type ProviderEvaluation } from './contract.js';
import { EvaluationError } from './errors.js';
import { boundedResponse } from './transport.js';

export async function evaluateVercel(
  state: AgentState,
  configuration: EvaluationConfiguration,
  signal: AbortSignal,
  modelOverride?: EvaluationModel,
): Promise<ProviderEvaluation> {
  const gateway = createGateway({
    apiKey: configuration.apiKey,
    baseURL: 'https://ai-gateway.vercel.sh/v4/ai',
    fetch: async (url, init) => {
      if (String(url) !== 'https://ai-gateway.vercel.sh/v4/ai/evaluation-model') {
        throw new EvaluationError('request_failed', 'Unexpected Gateway endpoint.');
      }
      return boundedResponse(await fetch(url, { ...init, redirect: 'error' }), signal);
    },
  });
  const result = await evaluate({
    model: modelOverride ?? gateway.evaluationModel(configuration.model),
    state,
    questions: EVALUATION_QUESTIONS,
    maxRetries: 0,
    abortSignal: signal,
    providerOptions: { gateway: { zeroDataRetention: false } },
  });
  return {
    assessment: normalizeAssessment(result.answers, nextActionConfidence(result.providerMetadata)),
    rawAnswers: sanitizeTraceValue(result.answers),
    ...(result.providerMetadata === undefined ? {} : { providerMetadata: sanitizeTraceValue(result.providerMetadata) }),
    // Gateway's SDK response.modelId echoes the requested alias. It does not
    // identify an upstream served version, so do not invent one here.
  };
}
import type { AgentState } from '../types.js';
import type { EvaluationConfiguration } from '../config.js';
import { redactSensitiveText, sanitizeTraceValue } from '../logging/trace.js';
import { NATIVE_EVALUATION_QUESTIONS, isRecord, normalizeAssessment, servedModel, type ProviderEvaluation } from './contract.js';
import { EvaluationError, EvaluationHttpError, retryAfterMs } from './errors.js';
import { boundedResponse, parseEvaluationJson } from './transport.js';

export const NATIVE_EVALUATION_ENDPOINTS = {
  openrouter: 'https://openrouter.ai/api/alpha/decisions',
  typesafe: 'https://api.typesafe.ai/v1/systemone',
} as const;

export const NATIVE_JEV_ENDPOINTS = NATIVE_EVALUATION_ENDPOINTS;

export { NATIVE_EVALUATION_QUESTIONS } from './contract.js';

function errorStatus(body: unknown): number | undefined {
  if (!isRecord(body) || !isRecord(body.error)) return undefined;
  const code = body.error.code;
  if (typeof code === 'number' && Number.isInteger(code) && code >= 400 && code <= 599) return code;
  const metadata = isRecord(body.error.metadata) ? body.error.metadata : {};
  const kind = body.error.error_type ?? body.error.type ?? metadata.error_type ?? code;
  switch (kind) {
    case 'invalid_api_key': case 'authentication_error': return 401;
    case 'permission_error': case 'insufficient_permissions': return 403;
    case 'insufficient_credits': case 'billing_error': return 402;
    case 'model_not_found': case 'model_unavailable': return 404;
    case 'rate_limit_exceeded': return 429;
    case 'server': case 'overloaded_error': return 503;
    default: return undefined;
  }
}

export async function evaluateNative(
  state: AgentState,
  configuration: EvaluationConfiguration & { provider: 'openrouter' | 'typesafe' },
  signal: AbortSignal,
): Promise<ProviderEvaluation> {
  const response = await boundedResponse(await fetch(NATIVE_EVALUATION_ENDPOINTS[configuration.provider], {
    method: 'POST',
    headers: { Authorization: `Bearer ${configuration.apiKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: configuration.model, state, questions: NATIVE_EVALUATION_QUESTIONS }),
    signal,
    redirect: 'error',
  }), signal);
  let body: unknown;
  try {
    body = parseEvaluationJson(await response.text());
  } catch {
    if (!response.ok) throw new EvaluationHttpError(response.status, retryAfterMs(response.headers.get('retry-after')));
    throw new EvaluationError('invalid_response', 'Decision provider returned invalid JSON evaluation data.', { stage: 'json', category: 'shape' });
  }
  if (!response.ok || (isRecord(body) && body.error !== undefined)) {
    throw new EvaluationHttpError(response.ok ? errorStatus(body) ?? 400 : response.status, retryAfterMs(response.headers.get('retry-after')));
  }
  if (!isRecord(body) || body.refusal !== undefined || !isRecord(body.answers)) {
    throw new EvaluationError('invalid_response', 'Decision provider returned invalid evaluation data.', { stage: 'answers', category: 'shape' });
  }
  const nextAction = body.answers.nextAction;
  return {
    assessment: normalizeAssessment(body.answers, isRecord(nextAction) ? nextAction.confidence : undefined, true),
    rawAnswers: sanitizeTraceValue(body.answers),
    servedModel: redactSensitiveText(servedModel(body.model)),
  };
}

